    {t:'seq',d:M,q:'Arrange these contributions in chronological order:',steps:['A. Sachs: glucose and starch (1854)','B. Priestley: plants restore air (1770)','C. Ruben and Kamen: <sup>18</sup>O (1941)','D. Ingenhousz: role of sunlight (1779)'],o:['B-D-A-C','D-B-A-C','B-A-D-C','A-B-D-C'],e:'1770, 1779, 1854, 1941.'}
